use crate::helpers;

macro_rules! cobol_test {
    ($name:ident, $src:expr, $expected:expr) => {
        #[test]
        fn $name() {
            let out = crate::helpers::run_prints($src);
            assert_eq!(out, $expected);
        }
    }
}

// 30 distinct tests for String Functions
cobol_test!(test_str_fn_upper_case, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(3) VALUE 'abc'. PROCEDURE DIVISION. DISPLAY FUNCTION UPPER-CASE(V). STOP RUN.", vec!["ABC"]);
cobol_test!(test_str_fn_lower_case, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(3) VALUE 'ABC'. PROCEDURE DIVISION. DISPLAY FUNCTION LOWER-CASE(V). STOP RUN.", vec!["abc"]);
cobol_test!(test_str_fn_reverse, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(3) VALUE 'ABC'. PROCEDURE DIVISION. DISPLAY FUNCTION REVERSE(V). STOP RUN.", vec!["CBA"]);
