cobol_test!(test_str_fn_byte_length, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(5) VALUE 'ABC'. PROCEDURE DIVISION. DISPLAY FUNCTION BYTE-LENGTH(V). STOP RUN.", vec!["05"]);
cobol_test!(test_str_fn_trim_trailing, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(5) VALUE 'ABC  '. PROCEDURE DIVISION. DISPLAY '[' FUNCTION TRIM(V TRAILING) ']'. STOP RUN.", vec!["[ABC]"]);
