cobol_test!(test_str_fn_trim_both, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(5) VALUE ' ABC '. PROCEDURE DIVISION. DISPLAY '[' FUNCTION TRIM(V) ']'. STOP RUN.", vec!["[ABC]"]);
cobol_test!(test_str_fn_numval, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(5) VALUE '  123'. PROCEDURE DIVISION. DISPLAY FUNCTION NUMVAL(V). STOP RUN.", vec!["123"]);
cobol_test!(test_str_fn_numval_c, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X(7) VALUE '$ 123'. PROCEDURE DIVISION. DISPLAY FUNCTION NUMVAL-C(V). STOP RUN.", vec!["123"]);
cobol_test!(test_str_fn_ord, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC X VALUE 'A'. PROCEDURE DIVISION. DISPLAY FUNCTION ORD(V). STOP RUN.", vec!["66"]); // 'A' is 65 in ascii, ORD returns 1-based collating sequence position, so 66
cobol_test!(test_str_fn_char, "IDENTIFICATION DIVISION. PROGRAM-ID. T. DATA DIVISION. WORKING-STORAGE SECTION. 01 V PIC 99 VALUE 66. PROCEDURE DIVISION. DISPLAY FUNCTION CHAR(V). STOP RUN.", vec!["A"]);
